library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;
use work.wishbone_pkg.all;
use work.wbgenplus_pkg.all;
use work.genram_pkg.all;
use work.simple_demo_auto_pkg.all;

entity simple_demo_auto is
generic(
  g_statusbits  : natural := 16 --Number of bits in status register
);
Port(
  clk_sys_i   : std_logic;                                      -- Clock input for sys domain
  rst_sys_n_i : std_logic;                                      -- Reset input (active low) for sys domain
  count_i     : in  std_logic_vector(16-1 downto 0);            -- Shows Data Input Counter
  count_V_i   : in  std_logic_vector(1-1 downto 0);             -- Valid flag - count
  error_i     : in  std_logic_vector(1-1 downto 0);             -- Error control
  scpad_V_i   : in  std_logic_vector(1-1 downto 0);             -- Valid flag - scpad
  stall_i     : in  std_logic_vector(1-1 downto 0);             -- flow control
  status_i    : in  std_logic_vector(g_statusbits-1 downto 0);  -- Shows if the devices are rdy/busy
  status_V_i  : in  std_logic_vector(1-1 downto 0);             -- Valid flag - status
  mode_o      : out std_logic_vector(8-1 downto 0);             -- Mode
  mode_RD_o   : out std_logic_vector(1-1 downto 0);             -- Read enable flag - mode
  mode_WR_o   : out std_logic_vector(1-1 downto 0);             -- Write enable flag - mode
  scpad_o     : out std_logic_vector(64-1 downto 0);            -- Scratchpad. Can be modified from Bus or outer entity
  scpad_i     : in  std_logic_vector(64-1 downto 0);            -- Scratchpad. Can be modified from Bus or outer entity
  scpad_RD_o  : out std_logic_vector(1-1 downto 0);             -- Read enable flag - scpad
  scpad_WR_o  : out std_logic_vector(1-1 downto 0);             -- Write enable flag - scpad
  
  slave_i     : in  t_wishbone_slave_in;
  slave_o     : out t_wishbone_slave_out

  
);
end simple_demo_auto;

architecture rtl of simple_demo_auto is

  signal s_pop, s_push    : std_logic;
  signal s_empty, s_full  : std_logic;
  signal r_e_wait, s_e_p  : std_logic;
  signal s_stall          : std_logic;
  signal s_valid,
         s_valid_ok,
         r_valid_check    : std_logic;
  signal r_ack            : std_logic;
  signal r_err            : std_logic;
  signal s_e, r_e, s_w    : std_logic;
  signal s_d              : std_logic_vector(32-1 downto 0);
  signal s_s              : std_logic_vector(4-1 downto 0);
  signal s_a              : std_logic_vector(3-1 downto 0);
  signal s_a_ext,
         r_a_ext0,
         r_a_ext1         : std_logic_vector(5-1 downto 0);
  signal r_error          : std_logic_vector(1-1 downto 0)            := std_logic_vector(to_unsigned(0, 1)); -- Error
  signal s_error_i        : std_logic_vector(1-1 downto 0)            := (others => '0');                     -- Error control
  signal s_stall_i        : std_logic_vector(1-1 downto 0)            := (others => '0');                     -- flow control
  signal r_status_V       : std_logic_vector(1-1 downto 0)            := (others => '0');                     -- Valid flag - status
  signal s_status_V_i     : std_logic_vector(1-1 downto 0)            := (others => '0');                     -- Valid flag - status
  signal r_status         : std_logic_vector(g_statusbits-1 downto 0) := (others => '0');                     -- Shows if the devices are rdy/busy
  signal s_status_i       : std_logic_vector(g_statusbits-1 downto 0) := (others => '0');                     -- Shows if the devices are rdy/busy
  signal r_mode_WR        : std_logic_vector(1-1 downto 0)            := std_logic_vector(to_unsigned(0, 1)); -- Write enable flag - mode
  signal r_mode_RD        : std_logic_vector(1-1 downto 0)            := std_logic_vector(to_unsigned(0, 1)); -- Read enable flag - mode
  signal r_mode           : std_logic_vector(8-1 downto 0)            := x"ff";                               -- Mode
  signal r_scpad_WR       : std_logic_vector(1-1 downto 0)            := std_logic_vector(to_unsigned(0, 1)); -- Write enable flag - scpad
  signal r_scpad_RD       : std_logic_vector(1-1 downto 0)            := std_logic_vector(to_unsigned(0, 1)); -- Read enable flag - scpad
  signal r_scpad_V        : std_logic_vector(1-1 downto 0)            := (others => '0');                     -- Valid flag - scpad
  signal s_scpad_V_i      : std_logic_vector(1-1 downto 0)            := (others => '0');                     -- Valid flag - scpad
  signal r_scpad          : std_logic_vector(64-1 downto 0)           := (others => '0');                     -- Scratchpad. Can be modified from Bus or outer entity
  signal s_scpad_i        : std_logic_vector(64-1 downto 0)           := (others => '0');                     -- Scratchpad. Can be modified from Bus or outer entity
  signal r_count_V        : std_logic_vector(1-1 downto 0)            := (others => '0');                     -- Valid flag - count
  signal s_count_V_i      : std_logic_vector(1-1 downto 0)            := (others => '0');                     -- Valid flag - count
  signal r_count          : std_logic_vector(16-1 downto 0)           := (others => '0');                     -- Shows Data Input Counter
  signal s_count_i        : std_logic_vector(16-1 downto 0)           := (others => '0');                     -- Shows Data Input Counter


begin

  sp : wb_skidpad
  generic map(
    g_adrbits   => 3
  )
  Port map(
    clk_i        => clk_sys_i,
    rst_n_i      => rst_sys_n_i,
    push_i       => s_push,
    pop_i        => s_pop,
    full_o       => s_full,
    empty_o      => s_empty,
    adr_i        => slave_i.adr(4 downto 2),
    dat_i        => slave_i.dat,
    sel_i        => slave_i.sel,
    we_i         => slave_i.we,
    adr_o        => s_a,
    dat_o        => s_d,
    sel_o        => s_s,
    we_o         => s_w
  );

  validmux: with to_integer(unsigned(s_a_ext)) select
  s_valid <= 
  s_status_V_i(0) when c_status_GET,  -- 
  s_scpad_V_i(0)  when c_scpad_RW_0,  -- 
  s_scpad_V_i(0)  when c_scpad_RW_1,  -- 
  s_count_V_i(0)  when c_count_GET,   -- 
  '1'             when others;
  
  s_valid_ok        <=  r_valid_check and s_valid;
  s_e_p             <=  r_e or r_e_wait;
  s_a_ext           <= s_a & "00";
  s_stall           <= s_full;
  s_push            <= slave_i.cyc and slave_i.stb and not s_stall;
  s_e               <= not (s_empty or s_e_p);
  s_pop             <= s_valid_ok;
  slave_o.stall     <= s_stall;
  
  s_error_i     <= error_i;
  s_stall_i     <= stall_i;
  s_status_V_i  <= status_V_i;
  s_status_i    <= status_i;
  mode_WR_o     <= r_mode_WR;
  mode_RD_o     <= r_mode_RD;
  mode_o        <= r_mode;
  scpad_WR_o    <= r_scpad_WR;
  scpad_RD_o    <= r_scpad_RD;
  s_scpad_V_i   <= scpad_V_i;
  s_scpad_i     <= scpad_i;
  scpad_o       <= r_scpad;
  s_count_V_i   <= count_V_i;
  s_count_i     <= count_i;
  
  slave : process(clk_sys_i)
  begin
    if rising_edge(clk_sys_i) then
      if(rst_sys_n_i = '0') then
        r_e           <= '0';
        r_e_wait      <= '0';
        r_valid_check <= '0';
        r_error     <= std_logic_vector(to_unsigned(0, 1));
        r_status    <= (others => '0');
        r_mode_WR   <= std_logic_vector(to_unsigned(0, 1));
        r_mode_RD   <= std_logic_vector(to_unsigned(0, 1));
        r_mode      <= x"ff";
        r_scpad_WR  <= std_logic_vector(to_unsigned(0, 1));
        r_scpad_RD  <= std_logic_vector(to_unsigned(0, 1));
        r_scpad     <= (others => '0');
        r_count     <= (others => '0');
      else
        r_e           <= s_e;
        r_a_ext0      <= s_a_ext;
        r_a_ext1      <= r_a_ext0;
        r_e_wait      <= s_e_p and not s_valid_ok;
        r_valid_check <= (r_valid_check or (s_e_p and not stall_i(0))) and not s_valid_ok;
        r_ack         <= s_pop and not (error_i(0) or r_error(0));
        r_err         <= s_pop and     (error_i(0) or r_error(0));
        slave_o.ack   <= r_ack;
        slave_o.err   <= r_err;
        
        
        if stall_i = "0" then
          r_error     <= (others => '0');
          r_mode_RD   <= (others => '0');
          r_mode_WR   <= (others => '0');
          r_scpad_RD  <= (others => '0');
          r_scpad_WR  <= (others => '0');
        end if;
        
        if s_count_V_i  = "1" then r_count  <= s_count_i; end if;   -- 
        if s_scpad_V_i  = "1" then r_scpad  <= s_scpad_i; end if;   -- 
        if s_status_V_i = "1" then r_status <= s_status_i; end if;  -- 
        
        
        if(s_e = '1') then
          if(s_w = '1') then
            -- WISHBONE WRITE ACTIONS
            case to_integer(unsigned(s_a_ext)) is
              when c_mode_CLR       => r_mode                 <= f_wb_wr(r_mode, s_d, s_s, "clr");                -- 
              r_mode_WR                                       <= (others  => '1');
              when c_mode_SET       => r_mode                 <= f_wb_wr(r_mode, s_d, s_s, "set");                -- 
              r_mode_WR                                       <= (others  => '1');
              when c_scpad_RW_0     => r_scpad(31 downto 0)   <= f_wb_wr(r_scpad(31 downto 0), s_d, s_s, "owr");  -- 
              r_scpad_WR                                      <= (others => '1');
              when c_scpad_RW_1     => r_scpad(63 downto 32)  <= f_wb_wr(r_scpad(63 downto 32), s_d, s_s, "owr"); -- 
              r_scpad_WR                                      <= (others => '1');
              when others           => r_error                <= "1";
            end case;
          else
            -- WISHBONE READ ACTIONS
            case to_integer(unsigned(s_a_ext)) is
              when c_status_GET     => null;
              when c_mode_GET       => null;
              r_mode_RD <= (others  => '1');
              when c_scpad_RW_0     => null;
              r_scpad_RD <= (others => '1');
              when c_scpad_RW_1     => null;
              r_scpad_RD <= (others => '1');
              when c_count_GET      => null;
              when others           => r_error <= "1";
            end case;
          end if; -- s_w
        end if; -- s_e
        
        case to_integer(unsigned(r_a_ext1)) is
          when c_status_GET => slave_o.dat  <= std_logic_vector(resize(unsigned(r_status), slave_o.dat'length));                -- 
          when c_mode_GET   => slave_o.dat  <= std_logic_vector(resize(unsigned(r_mode), slave_o.dat'length));                  -- 
          when c_scpad_RW_0 => slave_o.dat  <= std_logic_vector(resize(unsigned(r_scpad(31 downto 0)), slave_o.dat'length));    -- 
          when c_scpad_RW_1 => slave_o.dat  <= std_logic_vector(resize(unsigned(r_scpad(63 downto 32)), slave_o.dat'length));   -- 
          when c_count_GET  => slave_o.dat  <= std_logic_vector(resize(unsigned(r_count), slave_o.dat'length));                 -- 
          when others       => slave_o.dat  <= (others => 'X');
        end case;

        
      end if; -- rst
    end if; -- clk edge
  end process;

end rtl;
